<?php declare(strict_types=1); namespace App\Domains\WorkCore\System\Modules\Reviews\Actions; use App\Domains\WorkCore\System\Actions\{ActionHandlerResult,ActionRequest,PendingDomainEvent}; use App\Domains\WorkCore\System\Actions\Contracts\BusinessActionHandlerContract; use App\Domains\WorkCore\System\Modules\Reviews\Contracts\ReviewRepositoryContract; use App\Domains\WorkCore\System\References\TypedReference; final class RequestRebooking implements BusinessActionHandlerContract { public function __construct(private ReviewRepositoryContract $repository){} public function handle(ActionRequest $r): ActionHandlerResult {$x=$this->repository->requestRebooking($r->payload,$r->companyId,$r->actorId);return new ActionHandlerResult($x,new TypedReference('rebooking_request',(string)$x['public_id']),[new PendingDomainEvent('workcore.rebooking.requested',1,['request'=>$x])]);}}
